import { getReplaceableAddress, isEvent } from "./event.js";
import { getReplaceableAddressFromPointer, isAddressPointer, isEventPointer, } from "./pointers.js";
/** Build an array of filters that match other events "e" or "a" tagging this event */
export function buildCommonEventRelationFilters(base, pointer) {
    const filters = [];
    const id = typeof pointer === "string" ? pointer : isEventPointer(pointer) ? pointer.id : undefined;
    if (id)
        filters.push({ ...base, "#e": [id] });
    const address = isAddressPointer(pointer)
        ? getReplaceableAddressFromPointer(pointer)
        : isEvent(pointer)
            ? getReplaceableAddress(pointer)
            : undefined;
    if (address)
        filters.push({ ...base, "#a": [address] });
    return filters;
}
